{
  "name": "实验仪器数据库",
  "name_en": "Instrument Database",
  "manufacturer": "",
  "description": "用于实验室自动化的仪器配置数据库组件，主要管理仪器条目、EPICS 过程变量（PV）、配置说明以及已保存的位置状态，并可将相关 PV 恢复到预设值。它更像是实验控制系统中的数据管理服务，而非独立的物理仪器。",
  "description_en": "A laboratory automation database component used to manage instrument entries, EPICS process variables (PVs), configuration notes, and saved positions, and to restore related PVs to predefined values. It is a data-management service within an experimental control system rather than a standalone physical instrument.",
  "tag_hints": [
    "EPICS PV management",
    "instrument configuration database",
    "saved positions",
    "laboratory automation",
    "process variables",
    "instrument metadata"
  ],
  "actions": [
    {
      "action_name": "auto-connect_pvs",
      "description": "连接数据库中登记的 PV。",
      "description_en": "Connect the PVs registered in the database."
    },
    {
      "action_name": "auto-create_newdb",
      "description": "创建新的空数据库。",
      "description_en": "Create a new empty database."
    },
    {
      "action_name": "auto-check_version",
      "description": "检查数据库版本兼容性。",
      "description_en": "Check database version compatibility."
    },
    {
      "action_name": "auto-commit",
      "description": "提交当前数据库会话中的更改。",
      "description_en": "Commit the current database session changes."
    },
    {
      "action_name": "auto-query",
      "description": "执行通用数据库查询。",
      "description_en": "Execute a generic database query."
    },
    {
      "action_name": "auto-set_hostpid",
      "description": "设置主机名和进程 ID 信息。",
      "description_en": "Set the hostname and process ID information."
    },
    {
      "action_name": "auto-check_hostpid",
      "description": "检查已存储的主机名和进程 ID 是否与当前一致。",
      "description_en": "Check whether the stored hostname and process ID match the current ones."
    },
    {
      "action_name": "auto-set_config",
      "description": "设置配置名称和备注。",
      "description_en": "Set the configuration name and notes."
    },
    {
      "action_name": "auto-get_config",
      "description": "获取指定配置数据。",
      "description_en": "Get the specified configuration data."
    },
    {
      "action_name": "auto-set_admin_password",
      "description": "设置管理员密码。",
      "description_en": "Set the administrator password."
    },
    {
      "action_name": "auto-check_admin_password",
      "description": "校验管理员密码。",
      "description_en": "Verify the administrator password."
    },
    {
      "action_name": "auto-get_all_instruments",
      "description": "获取全部仪器条目。",
      "description_en": "Get all instrument entries."
    },
    {
      "action_name": "auto-get_instrument",
      "description": "按名称获取仪器条目。",
      "description_en": "Get an instrument entry by name."
    },
    {
      "action_name": "auto-get_instrument_pvs",
      "description": "获取某仪器关联的 PV 列表。",
      "description_en": "Get the PV list associated with an instrument."
    },
    {
      "action_name": "auto-map_pvtypes",
      "description": "建立 PV 类型映射。",
      "description_en": "Build the PV type mapping."
    },
    {
      "action_name": "auto-get_pvtypes",
      "description": "获取某 PV 可用的类型选项。",
      "description_en": "Get the available type choices for a PV."
    },
    {
      "action_name": "auto-get_pvtype",
      "description": "获取某 PV 的类型。",
      "description_en": "Get the type of a PV."
    },
    {
      "action_name": "auto-set_pvtype",
      "description": "设置某 PV 的类型。",
      "description_en": "Set the type of a PV."
    },
    {
      "action_name": "auto-get_allpvs",
      "description": "获取全部 PV 条目。",
      "description_en": "Get all PV entries."
    },
    {
      "action_name": "auto-get_pv",
      "description": "按名称获取 PV 条目。",
      "description_en": "Get a PV entry by name."
    },
    {
      "action_name": "auto-rename_position",
      "description": "重命名已保存的位置。",
      "description_en": "Rename a saved position."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取已保存的位置条目。",
      "description_en": "Get a saved position entry."
    },
    {
      "action_name": "auto-get_positions",
      "description": "获取某仪器的已保存位置名称列表。",
      "description_en": "Get the list of saved position names for an instrument."
    },
    {
      "action_name": "auto-get_positionlist",
      "description": "获取某仪器的已保存位置名称列表。",
      "description_en": "Get the list of saved position names for an instrument."
    },
    {
      "action_name": "auto-add_instrument",
      "description": "添加新的仪器条目。",
      "description_en": "Add a new instrument entry."
    },
    {
      "action_name": "auto-add_instrument_pvs",
      "description": "为仪器添加 PV。",
      "description_en": "Add PVs to an instrument."
    },
    {
      "action_name": "auto-remove_instrument_pv",
      "description": "从仪器中移除 PV。",
      "description_en": "Remove a PV from an instrument."
    },
    {
      "action_name": "auto-add_pv",
      "description": "添加新的 PV 条目。",
      "description_en": "Add a new PV entry."
    },
    {
      "action_name": "auto-remove_position",
      "description": "删除已保存的位置。",
      "description_en": "Remove a saved position."
    },
    {
      "action_name": "auto-remove_instrument",
      "description": "删除仪器条目。",
      "description_en": "Remove an instrument entry."
    },
    {
      "action_name": "auto-save_position",
      "description": "保存仪器的命名位置状态。",
      "description_en": "Save a named position state for an instrument."
    },
    {
      "action_name": "auto-get_position_values",
      "description": "获取已保存位置对应的 PV 数值。",
      "description_en": "Get the PV values stored for a saved position."
    },
    {
      "action_name": "auto-restore_position",
      "description": "将仪器恢复到已保存的位置状态。",
      "description_en": "Restore an instrument to a saved position state."
    },
    {
      "action_name": "auto-restore_complete",
      "description": "检查位置恢复是否完成。",
      "description_en": "Check whether position restoration is complete."
    }
  ]
}

